-- Seventh fixed refund commands. Native transaction and consumption order is authoritative.

CREATE OR REPLACE FUNCTION public.order_refund_order_locator_v1(p_order numeric)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER
SET search_path=pg_catalog,public SET TimeZone='UTC' AS $order_rpc$
DECLARE o public.orders%ROWTYPE;
failure_state text;failure_constraint text;
BEGIN
 IF current_user<>'authenticated' OR auth.role() IS DISTINCT FROM 'authenticated' OR auth.uid() IS DISTINCT FROM '__ORDER_SERVICE_UID__' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ORDER_RUNTIME_FORBIDDEN';END IF;
 BEGIN
IF p_order IS NULL OR p_order<0 OR p_order>18446744073709551615 OR p_order<>trunc(p_order) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
SELECT id,prepayment_id,user_id,pickup_at INTO o.id,o.prepayment_id,o.user_id,o.pickup_at FROM public.orders WHERE id=p_order;IF NOT FOUND THEN RETURN jsonb_build_object('outcome','NOT_FOUND');END IF;IF o.id IS NULL OR o.prepayment_id IS NULL OR o.user_id IS NULL OR o.pickup_at IS NULL OR NOT isfinite(o.pickup_at) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;RETURN jsonb_build_object('outcome','FOUND','locator',jsonb_build_object('order_id',o.id::text,'prepayment_id',o.prepayment_id::text,'user_id',o.user_id::text,'pickup_kind',(CASE WHEN o.pickup_at IS NULL THEN 'NULL' WHEN o.pickup_at='infinity'::timestamptz THEN 'POSITIVE_INFINITY' WHEN o.pickup_at='-infinity'::timestamptz THEN 'NEGATIVE_INFINITY' ELSE 'FINITE' END),'pickup_microseconds',(CASE WHEN o.pickup_at IS NOT NULL AND isfinite(o.pickup_at) THEN (extract(epoch FROM o.pickup_at)*1000000-946684800000000)::bigint::text ELSE NULL END)));
 EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS failure_state=RETURNED_SQLSTATE,failure_constraint=CONSTRAINT_NAME;
 IF failure_state='P1000' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;RETURN jsonb_build_object('outcome','UNAVAILABLE');
 END;
END
$order_rpc$;

CREATE OR REPLACE FUNCTION public.order_refund_request_order_v1(p_actor_kind text,p_actor numeric,p_locator jsonb,p_reason_hex text,p_key_hash text,p_request_hash text,p_now jsonb,p_notify_url_hex text)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER
SET search_path=pg_catalog,public SET TimeZone='UTC' AS $order_rpc$
DECLARE r public.refunds%ROWTYPE;p public.prepayments%ROWTYPE;o public.orders%ROWTYPE;a public.merchant_accounts%ROWTYPE;merchant boolean;key_bytes bytea;scope bytea;reason text;notify text;request_json text;req jsonb;provider_text text;pg_us numeric;now_at timestamptz;receipt jsonb;affected bigint;out_no text;evidence text;before_state text;raw_bytes bytea;text_value text;i integer;width integer;lead integer;next_byte integer;j integer;json_piece text;out_trade_json text;transaction_json text;payment_id numeric;order_id numeric;
failure_state text;failure_constraint text;
BEGIN
 IF current_user<>'authenticated' OR auth.role() IS DISTINCT FROM 'authenticated' OR auth.uid() IS DISTINCT FROM '__ORDER_SERVICE_UID__' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ORDER_RUNTIME_FORBIDDEN';END IF;
 BEGIN
IF p_actor IS NULL OR p_actor<0 OR p_actor>18446744073709551615 OR p_actor<>trunc(p_actor) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_reason_hex IS NULL OR p_reason_hex !~ '^([0-9a-f]{2})*$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_notify_url_hex IS NULL OR p_notify_url_hex !~ '^([0-9a-f]{2})*$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_key_hash IS NULL OR p_key_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_actor_kind IS NULL OR p_actor_kind NOT IN ('USER','MERCHANT') THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
merchant:=p_actor_kind='MERCHANT';reason:=convert_from(decode(p_reason_hex,'hex'),'UTF8');notify:=convert_from(decode(p_notify_url_hex,'hex'),'UTF8');key_bytes:=decode(p_key_hash,'hex');
IF jsonb_typeof(p_locator) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_locator))<>4 OR jsonb_typeof(p_locator->'order_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_locator->'prepayment_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_locator->'user_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_locator->'pickup_at') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_locator->>'order_id' IS NULL OR p_locator->>'order_id' !~ '^(0|[1-9][0-9]*)$' OR (p_locator->>'order_id')::numeric>18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_locator->>'prepayment_id' IS NULL OR p_locator->>'prepayment_id' !~ '^(0|[1-9][0-9]*)$' OR (p_locator->>'prepayment_id')::numeric>18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_locator->>'user_id' IS NULL OR p_locator->>'user_id' !~ '^(0|[1-9][0-9]*)$' OR (p_locator->>'user_id')::numeric>18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF jsonb_typeof((p_locator->'pickup_at')) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys((p_locator->'pickup_at')))<>4 OR jsonb_typeof((p_locator->'pickup_at')->'epoch_seconds') IS DISTINCT FROM 'string' OR jsonb_typeof((p_locator->'pickup_at')->'nanosecond') IS DISTINCT FROM 'number' OR jsonb_typeof((p_locator->'pickup_at')->'zero') IS DISTINCT FROM 'boolean' OR jsonb_typeof((p_locator->'pickup_at')->'canonical') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF (p_locator->'pickup_at')->>'epoch_seconds' !~ '^(0|-?[1-9][0-9]*)$' OR ((p_locator->'pickup_at')->>'epoch_seconds')::numeric NOT BETWEEN -9223372036854775808 AND 9223372036854775807 OR (p_locator->'pickup_at')->>'nanosecond' !~ '^(0|[1-9][0-9]*)$' OR ((p_locator->'pickup_at')->>'nanosecond')::numeric NOT BETWEEN 0 AND 999999999 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
order_id:=(p_locator->>'order_id')::numeric;payment_id:=(p_locator->>'prepayment_id')::numeric;IF merchant THEN SELECT id,role,auth_version INTO a.id,a.role,a.auth_version FROM public.merchant_accounts WHERE bound_user_id=p_actor AND enabled=true AND deleted_at IS NULL AND role='OWNER' FOR UPDATE;IF NOT FOUND THEN RETURN jsonb_build_object('outcome','FORBIDDEN');END IF;IF a.id IS NULL OR a.auth_version IS NULL OR a.id NOT BETWEEN 0 AND 18446744073709551615 OR a.auth_version NOT BETWEEN 0 AND 18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;END IF;
SELECT out_trade_no,expected_mchid,expected_amount_cents,currency INTO p.out_trade_no,p.expected_mchid,p.expected_amount_cents,p.currency FROM public.prepayments WHERE id=payment_id FOR UPDATE;IF NOT FOUND THEN RETURN jsonb_build_object('outcome','NOT_FOUND');END IF;IF p.out_trade_no IS NULL OR p.expected_mchid IS NULL OR p.expected_amount_cents IS NULL OR p.currency IS NULL OR p.expected_amount_cents NOT BETWEEN 0 AND 18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
SELECT id,user_id,state,transaction_id,order_no,pickup_at,payable_cents,refunding_at INTO o.id,o.user_id,o.state,o.transaction_id,o.order_no,o.pickup_at,o.payable_cents,o.refunding_at FROM public.orders WHERE id=order_id FOR UPDATE;IF NOT FOUND THEN RETURN jsonb_build_object('outcome','NOT_FOUND');END IF;IF o.id IS NULL OR o.user_id IS NULL OR o.state IS NULL OR o.transaction_id IS NULL OR o.order_no IS NULL OR o.pickup_at IS NULL OR NOT isfinite(o.pickup_at) OR o.payable_cents IS NULL OR o.id NOT BETWEEN 0 AND 18446744073709551615 OR o.user_id NOT BETWEEN 0 AND 18446744073709551615 OR o.payable_cents NOT BETWEEN 0 AND 18446744073709551615 OR (o.refunding_at IS NOT NULL AND NOT isfinite(o.refunding_at)) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;IF o.user_id<>(p_locator->>'user_id')::numeric OR o.payable_cents<>p.expected_amount_cents THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;IF NOT merchant AND o.user_id<>p_actor THEN RETURN jsonb_build_object('outcome','NOT_FOUND');END IF;
scope:=CASE WHEN merchant THEN sha256(convert_to('merchant:'||p_actor::text||':'||a.id::text,'UTF8')) ELSE sha256(convert_to('USER','UTF8')||decode('00','hex')||int8send((CASE WHEN p_actor>9223372036854775807 THEN p_actor-18446744073709551616 ELSE p_actor END)::bigint)) END;
SELECT * INTO r FROM public.refunds WHERE prepayment_id=payment_id;IF FOUND THEN
IF r.id IS NULL OR r.prepayment_id IS NULL OR r.provider_state IS NULL OR r.materialization_state IS NULL OR r.amount_cents IS NULL OR r.currency IS NULL OR r.created_at IS NULL OR NOT isfinite(r.created_at) OR r.id NOT BETWEEN 0 AND 18446744073709551615 OR r.prepayment_id NOT BETWEEN 0 AND 18446744073709551615 OR r.order_id NOT BETWEEN 0 AND 18446744073709551615 OR r.amount_cents NOT BETWEEN 0 AND 18446744073709551615 OR r.requested_by_user_id NOT BETWEEN 0 AND 18446744073709551615 OR r.requested_by_account_id NOT BETWEEN 0 AND 18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF r.idempotency_key_hash<>key_bytes OR r.reason_code<>reason OR (merchant AND coalesce(r.requested_by_account_id,0)<>a.id) OR (NOT merchant AND coalesce(r.requested_by_user_id,0)<>p_actor) THEN RETURN jsonb_build_object('outcome','IDEMPOTENCY_CONFLICT');END IF;
SELECT response_json INTO receipt FROM public.action_audits WHERE entry_kind='COMMAND_RECEIPT' AND actor_scope_hash=scope AND action='refund.request' AND operation_key_hash=key_bytes;IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;RETURN jsonb_build_object('outcome','REQUESTED','receipt',receipt::text,'is_new',false,'refund_id',r.id::text,'prepayment_id',r.prepayment_id::text);END IF;
IF jsonb_typeof(p_now) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_now))<>4 OR jsonb_typeof(p_now->'epoch_seconds') IS DISTINCT FROM 'string' OR jsonb_typeof(p_now->'nanosecond') IS DISTINCT FROM 'number' OR jsonb_typeof(p_now->'zero') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_now->'canonical') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_now->>'epoch_seconds' !~ '^(0|-?[1-9][0-9]*)$' OR (p_now->>'epoch_seconds')::numeric NOT BETWEEN -9223372036854775808 AND 9223372036854775807 OR p_now->>'nanosecond' !~ '^(0|[1-9][0-9]*)$' OR (p_now->>'nanosecond')::numeric NOT BETWEEN 0 AND 999999999 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF merchant THEN IF o.state NOT IN ('RESERVED','PREPARING','READY_FOR_PICKUP','COMPLETED') THEN RETURN jsonb_build_object('outcome','TRANSITION_NOT_ALLOWED');END IF;ELSIF o.state<>'RESERVED' OR NOT extract(epoch FROM o.pickup_at)*1000000000>((p_now->>'epoch_seconds')::numeric*1000000000+(p_now->>'nanosecond')::numeric)+1800000000000 THEN RETURN jsonb_build_object('outcome','TRANSITION_NOT_ALLOWED');END IF;before_state:=o.state;
out_no:='ORDER_REFUND_'||payment_id::text;req:=jsonb_build_object('out_refund_no',out_no,'reason',reason,'notify_url',notify,'amount_cents',p.expected_amount_cents,'total_cents',p.expected_amount_cents,'currency',p.currency);
raw_bytes:=p.out_trade_no;text_value:='';i:=0;WHILE i<octet_length(raw_bytes) LOOP lead:=get_byte(raw_bytes,i);width:=CASE WHEN lead<128 THEN 1 WHEN lead BETWEEN 194 AND 223 THEN 2 WHEN lead BETWEEN 224 AND 239 THEN 3 WHEN lead BETWEEN 240 AND 244 THEN 4 ELSE 0 END;IF width>0 AND i+width<=octet_length(raw_bytes) THEN IF width>1 THEN FOR j IN 1..width-1 LOOP IF get_byte(raw_bytes,i+j) NOT BETWEEN 128 AND 191 THEN width:=0;EXIT;END IF;END LOOP;END IF;IF width>0 AND lead IN (224,237,240,244) THEN next_byte:=get_byte(raw_bytes,i+1);IF (lead=224 AND next_byte<160) OR (lead=237 AND next_byte>159) OR (lead=240 AND next_byte<144) OR (lead=244 AND next_byte>143) THEN width:=0;END IF;END IF;ELSE width:=0;END IF;IF width=0 THEN text_value:=text_value||chr(65533);i:=i+1;ELSE text_value:=text_value||convert_from(substring(raw_bytes,i+1,width),'UTF8');i:=i+width;END IF;END LOOP;provider_text:=text_value;
req:=req||jsonb_build_object('out_trade_no',provider_text);
raw_bytes:=o.transaction_id;text_value:='';i:=0;WHILE i<octet_length(raw_bytes) LOOP lead:=get_byte(raw_bytes,i);width:=CASE WHEN lead<128 THEN 1 WHEN lead BETWEEN 194 AND 223 THEN 2 WHEN lead BETWEEN 224 AND 239 THEN 3 WHEN lead BETWEEN 240 AND 244 THEN 4 ELSE 0 END;IF width>0 AND i+width<=octet_length(raw_bytes) THEN IF width>1 THEN FOR j IN 1..width-1 LOOP IF get_byte(raw_bytes,i+j) NOT BETWEEN 128 AND 191 THEN width:=0;EXIT;END IF;END LOOP;END IF;IF width>0 AND lead IN (224,237,240,244) THEN next_byte:=get_byte(raw_bytes,i+1);IF (lead=224 AND next_byte<160) OR (lead=237 AND next_byte>159) OR (lead=240 AND next_byte<144) OR (lead=244 AND next_byte>143) THEN width:=0;END IF;END IF;ELSE width:=0;END IF;IF width=0 THEN text_value:=text_value||chr(65533);i:=i+1;ELSE text_value:=text_value||convert_from(substring(raw_bytes,i+1,width),'UTF8');i:=i+width;END IF;END LOOP;provider_text:=text_value;
req:=req||jsonb_build_object('transaction_id',provider_text);
raw_bytes:=p.out_trade_no;out_trade_json:='"';i:=0;WHILE i<octet_length(raw_bytes) LOOP lead:=get_byte(raw_bytes,i);width:=CASE WHEN lead<128 THEN 1 WHEN lead BETWEEN 194 AND 223 THEN 2 WHEN lead BETWEEN 224 AND 239 THEN 3 WHEN lead BETWEEN 240 AND 244 THEN 4 ELSE 0 END;IF width>0 AND i+width<=octet_length(raw_bytes) THEN IF width>1 THEN FOR j IN 1..width-1 LOOP IF get_byte(raw_bytes,i+j) NOT BETWEEN 128 AND 191 THEN width:=0;EXIT;END IF;END LOOP;END IF;IF width>0 AND lead IN (224,237,240,244) THEN next_byte:=get_byte(raw_bytes,i+1);IF (lead=224 AND next_byte<160) OR (lead=237 AND next_byte>159) OR (lead=240 AND next_byte<144) OR (lead=244 AND next_byte>143) THEN width:=0;END IF;END IF;ELSE width:=0;END IF;IF width=0 THEN out_trade_json:=out_trade_json||E'\\ufffd';i:=i+1;ELSE json_piece:=replace(replace(replace(replace(replace(to_json(convert_from(substring(raw_bytes,i+1,width),'UTF8'))::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029');out_trade_json:=out_trade_json||substring(json_piece,2,char_length(json_piece)-2);i:=i+width;END IF;END LOOP;out_trade_json:=out_trade_json||'"';
raw_bytes:=o.transaction_id;transaction_json:='"';i:=0;WHILE i<octet_length(raw_bytes) LOOP lead:=get_byte(raw_bytes,i);width:=CASE WHEN lead<128 THEN 1 WHEN lead BETWEEN 194 AND 223 THEN 2 WHEN lead BETWEEN 224 AND 239 THEN 3 WHEN lead BETWEEN 240 AND 244 THEN 4 ELSE 0 END;IF width>0 AND i+width<=octet_length(raw_bytes) THEN IF width>1 THEN FOR j IN 1..width-1 LOOP IF get_byte(raw_bytes,i+j) NOT BETWEEN 128 AND 191 THEN width:=0;EXIT;END IF;END LOOP;END IF;IF width>0 AND lead IN (224,237,240,244) THEN next_byte:=get_byte(raw_bytes,i+1);IF (lead=224 AND next_byte<160) OR (lead=237 AND next_byte>159) OR (lead=240 AND next_byte<144) OR (lead=244 AND next_byte>143) THEN width:=0;END IF;END IF;ELSE width:=0;END IF;IF width=0 THEN transaction_json:=transaction_json||E'\\ufffd';i:=i+1;ELSE json_piece:=replace(replace(replace(replace(replace(to_json(convert_from(substring(raw_bytes,i+1,width),'UTF8'))::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029');transaction_json:=transaction_json||substring(json_piece,2,char_length(json_piece)-2);i:=i+width;END IF;END LOOP;transaction_json:=transaction_json||'"';
request_json:='{"out_trade_no":'||out_trade_json;
IF req->>'transaction_id'<>'' THEN request_json:=request_json||',"transaction_id":'||transaction_json;END IF;
request_json:=request_json||',"out_refund_no":'||replace(replace(replace(replace(replace(to_json(req->>'out_refund_no')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029');
request_json:=request_json||',"reason":'||replace(replace(replace(replace(replace(to_json(req->>'reason')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029');
request_json:=request_json||',"notify_url":'||replace(replace(replace(replace(replace(to_json(req->>'notify_url')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029');
request_json:=request_json||',"amount_cents":'||(req->>'amount_cents')||',"total_cents":'||(req->>'total_cents')||',"currency":'||replace(replace(replace(replace(replace(to_json(req->>'currency')::text,'<',E'\\u003c'),'>',E'\\u003e'),'&',E'\\u0026'),chr(8232),E'\\u2028'),chr(8233),E'\\u2029')||'}';
IF jsonb_typeof(p_now) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_now))<>4 OR jsonb_typeof(p_now->'epoch_seconds') IS DISTINCT FROM 'string' OR jsonb_typeof(p_now->'nanosecond') IS DISTINCT FROM 'number' OR jsonb_typeof(p_now->'zero') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_now->'canonical') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_now->>'epoch_seconds' !~ '^(0|-?[1-9][0-9]*)$' OR (p_now->>'epoch_seconds')::numeric NOT BETWEEN -9223372036854775808 AND 9223372036854775807 OR p_now->>'nanosecond' !~ '^(0|[1-9][0-9]*)$' OR (p_now->>'nanosecond')::numeric NOT BETWEEN 0 AND 999999999 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
pg_us:=mod((p_now->>'epoch_seconds')::numeric*1000000+div((p_now->>'nanosecond')::numeric,1000)-946684800000000,18446744073709551616);IF pg_us<0 THEN pg_us:=pg_us+18446744073709551616;END IF;IF pg_us>=9223372036854775808 THEN pg_us:=pg_us-18446744073709551616;END IF;
IF pg_us=9223372036854775807 THEN now_at:='infinity'::timestamptz;ELSIF pg_us=-9223372036854775808 THEN now_at:='-infinity'::timestamptz;ELSE now_at:='2000-01-01T00:00:00Z'::timestamptz+(div(pg_us,86400000000)::text||' days '||mod(pg_us,86400000000)::text||' microseconds')::interval;END IF;
INSERT INTO public.refunds(prepayment_id,order_id,out_refund_no,idempotency_key_hash,amount_cents,currency,reason_code,requested_by_user_id,requested_by_account_id,provider_request_json,provider_request_digest,provider_state,create_attempted_at,provider_refund_id,materialization_state,pending_reason_code,materialized_at,lease_kind,lease_owner,lease_expires_at,record_version,next_query_at,created_at,updated_at) VALUES(payment_id,order_id,convert_to(out_no,'UTF8'),key_bytes,p.expected_amount_cents,p.currency,reason,CASE WHEN merchant THEN NULL ELSE p_actor END,CASE WHEN merchant THEN a.id ELSE NULL END,request_json::jsonb,sha256(convert_to(request_json,'UTF8')),'READY',NULL,NULL,'AWAITING_PROVIDER',NULL,NULL,NULL,NULL,NULL,1,NULL,now_at,now_at) RETURNING * INTO r;IF r.id=0 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
UPDATE public.orders SET state='REFUNDING',refunding_at=now_at,redemption_token_ciphertext=NULL,redemption_key_version=NULL,record_version=record_version+1,updated_at=now_at WHERE id=order_id AND record_version>0;GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
provider_text:='';receipt:=jsonb_build_object('ID',r.id,'PrepaymentID',r.prepayment_id,'OrderID',coalesce(r.order_id,0),'State',r.provider_state,'MaterializationState',r.materialization_state,'AmountCents',r.amount_cents,'Currency',r.currency,'RequestedAt',p_now->>'canonical','ProviderRefundID',provider_text,'PendingReason',coalesce(r.pending_reason_code,''));IF length(substring(p_now->>'canonical' FROM '^([0-9]+)-')) IS DISTINCT FROM 4 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
evidence:=encode(sha256(convert_to(coalesce(r.order_id,0)::text,'UTF8')||decode('00','hex')||convert_to(reason,'UTF8')),'hex');
INSERT INTO public.action_audits(entry_kind,actor_kind,actor_scope_hash,actor_user_id,actor_account_id,actor_account_id_snapshot,actor_role_snapshot,actor_auth_version_snapshot,action,target_type,target_id,operation_key_hash,request_id_hash,result,reason_code,before_state_json,after_state_json,response_json,occurred_at) VALUES('COMMAND_RECEIPT',CASE WHEN merchant THEN 'MERCHANT' ELSE 'USER' END,scope,p_actor,CASE WHEN merchant THEN a.id ELSE NULL END,CASE WHEN merchant THEN a.id ELSE NULL END,CASE WHEN merchant THEN a.role ELSE NULL END,CASE WHEN merchant THEN a.auth_version ELSE NULL END,'refund.request','REFUND',r.id,key_bytes,decode(p_request_hash,'hex'),'SUCCEEDED','REFUND_REQUESTED',jsonb_build_object('state',before_state,'request_digest',evidence),jsonb_build_object('state','REFUNDING'),receipt,now_at);RETURN jsonb_build_object('outcome','REQUESTED','receipt',receipt::text,'is_new',true,'refund_id',r.id::text,'prepayment_id',r.prepayment_id::text);
 EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS failure_state=RETURNED_SQLSTATE,failure_constraint=CONSTRAINT_NAME;
 IF failure_state IN ('40P01','40001','55P03') THEN RETURN jsonb_build_object('outcome','SQL_FAILURE','sqlstate',failure_state,'constraint','');END IF;
IF failure_state='23505' AND failure_constraint IN ('uq_refunds_prepayment','uq_refunds_order','uq_refunds_out_refund_no','uq_action_audits_command_receipt') THEN RETURN jsonb_build_object('outcome','SQL_FAILURE','sqlstate',failure_state,'constraint',failure_constraint);END IF;
IF failure_state='P1000' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
RAISE;
 END;
END
$order_rpc$;

CREATE OR REPLACE FUNCTION public.order_refund_request_paid_v1(p_actor numeric,p_prepayment numeric,p_reason_hex text,p_key_hash text,p_request_hash text,p_now jsonb,p_notify_url_hex text)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER
SET search_path=pg_catalog,public SET TimeZone='UTC' AS $order_rpc$
DECLARE r public.refunds%ROWTYPE;p public.prepayments%ROWTYPE;o public.orders%ROWTYPE;a public.merchant_accounts%ROWTYPE;merchant boolean;key_bytes bytea;scope bytea;reason text;notify text;request_json text;req jsonb;provider_text text;pg_us numeric;now_at timestamptz;receipt jsonb;affected bigint;out_no text;evidence text;before_state text;raw_bytes bytea;text_value text;i integer;width integer;lead integer;next_byte integer;j integer;json_piece text;out_trade_json text;transaction_json text;payment_id numeric;order_id numeric;
