RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER
SET search_path=pg_catalog,public SET TimeZone='UTC' AS $order_rpc$
DECLARE r public.refunds%ROWTYPE;
failure_state text;failure_constraint text;
BEGIN
 IF current_user<>'authenticated' OR auth.role() IS DISTINCT FROM 'authenticated' OR auth.uid() IS DISTINCT FROM '__ORDER_SERVICE_UID__' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ORDER_RUNTIME_FORBIDDEN';END IF;
 BEGIN
IF p_out_refund_no_hex IS NULL OR p_out_refund_no_hex !~ '^([0-9a-f]{2})*$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
SELECT id,prepayment_id,order_id INTO r.id,r.prepayment_id,r.order_id FROM public.refunds WHERE out_refund_no=decode(p_out_refund_no_hex,'hex');IF NOT FOUND THEN RETURN jsonb_build_object('outcome','NOT_FOUND');END IF;IF r.id IS NULL OR r.prepayment_id IS NULL OR r.id NOT BETWEEN 0 AND 18446744073709551615 OR r.prepayment_id NOT BETWEEN 0 AND 18446744073709551615 OR r.order_id NOT BETWEEN 0 AND 18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;RETURN jsonb_build_object('outcome','FOUND','locator',jsonb_build_object('refund_id',r.id::text,'prepayment_id',r.prepayment_id::text,'order_id',r.order_id::text));
 EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS failure_state=RETURNED_SQLSTATE,failure_constraint=CONSTRAINT_NAME;
 IF failure_state='P1000' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;RETURN jsonb_build_object('outcome','UNAVAILABLE');
 END;
END
$order_rpc$;

