pg_us:=mod((p_cutoff->>'epoch_seconds')::numeric*1000000+div((p_cutoff->>'nanosecond')::numeric,1000)-946684800000000,18446744073709551616);IF pg_us<0 THEN pg_us:=pg_us+18446744073709551616;END IF;IF pg_us>=9223372036854775808 THEN pg_us:=pg_us-18446744073709551616;END IF;
IF pg_us=9223372036854775807 THEN cutoff_at:='infinity'::timestamptz;ELSIF pg_us=-9223372036854775808 THEN cutoff_at:='-infinity'::timestamptz;ELSE cutoff_at:='2000-01-01T00:00:00Z'::timestamptz+(div(pg_us,86400000000)::text||' days '||mod(pg_us,86400000000)::text||' microseconds')::interval;END IF;
pg_us:=mod((p_lease_now->>'epoch_seconds')::numeric*1000000+div((p_lease_now->>'nanosecond')::numeric,1000)-946684800000000,18446744073709551616);IF pg_us<0 THEN pg_us:=pg_us+18446744073709551616;END IF;IF pg_us>=9223372036854775808 THEN pg_us:=pg_us-18446744073709551616;END IF;
IF pg_us=9223372036854775807 THEN lease_at:='infinity'::timestamptz;ELSIF pg_us=-9223372036854775808 THEN lease_at:='-infinity'::timestamptz;ELSE lease_at:='2000-01-01T00:00:00Z'::timestamptz+(div(pg_us,86400000000)::text||' days '||mod(pg_us,86400000000)::text||' microseconds')::interval;END IF;
IF (p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;SELECT coalesce(jsonb_agg(id::text ORDER BY id),'[]'::jsonb) INTO ids FROM (SELECT id FROM public.refunds WHERE provider_state='READY' OR ((provider_state='CREATE_CLAIMED' AND lease_expires_at<=lease_at) OR (provider_state IN ('CREATE_UNKNOWN','PROCESSING') AND (lease_expires_at IS NULL OR lease_expires_at<=lease_at) AND (next_query_at IS NULL OR next_query_at<=cutoff_at))) ORDER BY id LIMIT p_limit) due;RETURN jsonb_build_object('outcome','FOUND','ids',ids);
 EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS failure_state=RETURNED_SQLSTATE,failure_constraint=CONSTRAINT_NAME;
 IF failure_state='P1000' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;RETURN jsonb_build_object('outcome','UNAVAILABLE');
 END;
END
$order_rpc$;

CREATE OR REPLACE FUNCTION public.order_refund_claim_query_v1(p_refund numeric,p_owner_hex text,p_cutoff jsonb,p_now jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER
SET search_path=pg_catalog,public SET TimeZone='UTC' AS $order_rpc$
DECLARE r public.refunds%ROWTYPE;pg_us numeric;now_at timestamptz;expires_at timestamptz;expiry_ns numeric;expiry jsonb;affected bigint;not_claimed boolean:=false;
failure_state text;failure_constraint text;
BEGIN
 IF current_user<>'authenticated' OR auth.role() IS DISTINCT FROM 'authenticated' OR auth.uid() IS DISTINCT FROM '__ORDER_SERVICE_UID__' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ORDER_RUNTIME_FORBIDDEN';END IF;
 BEGIN
IF p_refund IS NULL OR p_refund<0 OR p_refund>18446744073709551615 OR p_refund<>trunc(p_refund) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
SELECT provider_state,out_refund_no,record_version,lease_expires_at,next_query_at INTO r.provider_state,r.out_refund_no,r.record_version,r.lease_expires_at,r.next_query_at FROM public.refunds WHERE id=p_refund FOR UPDATE;IF NOT FOUND OR r.provider_state IS NULL OR r.out_refund_no IS NULL OR r.record_version IS NULL OR r.record_version NOT BETWEEN 0 AND 18446744073709551615 OR (r.lease_expires_at IS NOT NULL AND NOT isfinite(r.lease_expires_at)) OR (r.next_query_at IS NOT NULL AND NOT isfinite(r.next_query_at)) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;IF jsonb_typeof(p_cutoff) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_cutoff))<>4 OR jsonb_typeof(p_cutoff->'epoch_seconds') IS DISTINCT FROM 'string' OR jsonb_typeof(p_cutoff->'nanosecond') IS DISTINCT FROM 'number' OR jsonb_typeof(p_cutoff->'zero') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_cutoff->'canonical') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_cutoff->>'epoch_seconds' !~ '^(0|-?[1-9][0-9]*)$' OR (p_cutoff->>'epoch_seconds')::numeric NOT BETWEEN -9223372036854775808 AND 9223372036854775807 OR p_cutoff->>'nanosecond' !~ '^(0|[1-9][0-9]*)$' OR (p_cutoff->>'nanosecond')::numeric NOT BETWEEN 0 AND 999999999 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF jsonb_typeof(p_now) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_now))<>4 OR jsonb_typeof(p_now->'epoch_seconds') IS DISTINCT FROM 'string' OR jsonb_typeof(p_now->'nanosecond') IS DISTINCT FROM 'number' OR jsonb_typeof(p_now->'zero') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_now->'canonical') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_now->>'epoch_seconds' !~ '^(0|-?[1-9][0-9]*)$' OR (p_now->>'epoch_seconds')::numeric NOT BETWEEN -9223372036854775808 AND 9223372036854775807 OR p_now->>'nanosecond' !~ '^(0|[1-9][0-9]*)$' OR (p_now->>'nanosecond')::numeric NOT BETWEEN 0 AND 999999999 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF NOT ((r.provider_state='CREATE_CLAIMED' AND r.lease_expires_at IS NOT NULL AND extract(epoch FROM r.lease_expires_at)*1000000000<=((p_now->>'epoch_seconds')::numeric*1000000000+(p_now->>'nanosecond')::numeric)) OR (r.provider_state IN ('CREATE_UNKNOWN','PROCESSING') AND (r.lease_expires_at IS NULL OR extract(epoch FROM r.lease_expires_at)*1000000000<=((p_now->>'epoch_seconds')::numeric*1000000000+(p_now->>'nanosecond')::numeric)) AND (r.next_query_at IS NULL OR extract(epoch FROM r.next_query_at)*1000000000<=((p_cutoff->>'epoch_seconds')::numeric*1000000000+(p_cutoff->>'nanosecond')::numeric)))) THEN RETURN jsonb_build_object('outcome','NOT_CLAIMED');END IF;pg_us:=mod((p_now->>'epoch_seconds')::numeric*1000000+div((p_now->>'nanosecond')::numeric,1000)-946684800000000,18446744073709551616);IF pg_us<0 THEN pg_us:=pg_us+18446744073709551616;END IF;IF pg_us>=9223372036854775808 THEN pg_us:=pg_us-18446744073709551616;END IF;
IF pg_us=9223372036854775807 THEN now_at:='infinity'::timestamptz;ELSIF pg_us=-9223372036854775808 THEN now_at:='-infinity'::timestamptz;ELSE now_at:='2000-01-01T00:00:00Z'::timestamptz+(div(pg_us,86400000000)::text||' days '||mod(pg_us,86400000000)::text||' microseconds')::interval;END IF;
expiry_ns:=((p_now->>'epoch_seconds')::numeric*1000000000+(p_now->>'nanosecond')::numeric)+30000000000;expiry:=jsonb_build_object('epoch_seconds',floor(expiry_ns/1000000000)::text,'nanosecond',expiry_ns-floor(expiry_ns/1000000000)*1000000000);
pg_us:=mod((expiry->>'epoch_seconds')::numeric*1000000+div((expiry->>'nanosecond')::numeric,1000)-946684800000000,18446744073709551616);IF pg_us<0 THEN pg_us:=pg_us+18446744073709551616;END IF;IF pg_us>=9223372036854775808 THEN pg_us:=pg_us-18446744073709551616;END IF;
IF pg_us=9223372036854775807 THEN expires_at:='infinity'::timestamptz;ELSIF pg_us=-9223372036854775808 THEN expires_at:='-infinity'::timestamptz;ELSE expires_at:='2000-01-01T00:00:00Z'::timestamptz+(div(pg_us,86400000000)::text||' days '||mod(pg_us,86400000000)::text||' microseconds')::interval;END IF;
IF p_owner_hex IS NULL OR p_owner_hex !~ '^[0-9a-f]{32}$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
UPDATE public.refunds SET provider_state=CASE WHEN provider_state='CREATE_CLAIMED' THEN 'CREATE_UNKNOWN' ELSE provider_state END,lease_kind='QUERY',lease_owner=decode(p_owner_hex,'hex'),lease_expires_at=expires_at,record_version=record_version+1,updated_at=now_at WHERE id=p_refund AND record_version=r.record_version;GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN not_claimed:=true;RAISE EXCEPTION USING ERRCODE='P1001',MESSAGE='ORDER_REFUND_NOT_CLAIMED';END IF;RETURN jsonb_build_object('outcome','CLAIMED','version',(r.record_version+1)::text,'out_refund_no_hex',encode(r.out_refund_no,'hex'));
 EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS failure_state=RETURNED_SQLSTATE,failure_constraint=CONSTRAINT_NAME;
 IF not_claimed THEN RETURN jsonb_build_object('outcome','NOT_CLAIMED');END IF;IF failure_state='P1000' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;RETURN jsonb_build_object('outcome','UNAVAILABLE');
 END;
END
$order_rpc$;

CREATE OR REPLACE FUNCTION public.order_refund_release_query_v1(p_refund numeric,p_owner_hex text,p_version numeric,p_now jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER
SET search_path=pg_catalog,public SET TimeZone='UTC' AS $order_rpc$
DECLARE r public.refunds%ROWTYPE;pg_us numeric;now_at timestamptz;expires_at timestamptz;expiry_ns numeric;expiry jsonb;
failure_state text;failure_constraint text;
BEGIN
 IF current_user<>'authenticated' OR auth.role() IS DISTINCT FROM 'authenticated' OR auth.uid() IS DISTINCT FROM '__ORDER_SERVICE_UID__' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ORDER_RUNTIME_FORBIDDEN';END IF;
 BEGIN
IF p_refund IS NULL OR p_refund<0 OR p_refund>18446744073709551615 OR p_refund<>trunc(p_refund) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_version IS NULL OR p_version<0 OR p_version>18446744073709551615 OR p_version<>trunc(p_version) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
SELECT lease_kind,lease_owner,record_version,lease_expires_at INTO r.lease_kind,r.lease_owner,r.record_version,r.lease_expires_at FROM public.refunds WHERE id=p_refund FOR UPDATE;IF NOT FOUND OR r.record_version IS NULL OR r.record_version NOT BETWEEN 0 AND 18446744073709551615 OR (r.lease_expires_at IS NOT NULL AND NOT isfinite(r.lease_expires_at)) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;IF jsonb_typeof(p_now) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_now))<>4 OR jsonb_typeof(p_now->'epoch_seconds') IS DISTINCT FROM 'string' OR jsonb_typeof(p_now->'nanosecond') IS DISTINCT FROM 'number' OR jsonb_typeof(p_now->'zero') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_now->'canonical') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_now->>'epoch_seconds' !~ '^(0|-?[1-9][0-9]*)$' OR (p_now->>'epoch_seconds')::numeric NOT BETWEEN -9223372036854775808 AND 9223372036854775807 OR p_now->>'nanosecond' !~ '^(0|[1-9][0-9]*)$' OR (p_now->>'nanosecond')::numeric NOT BETWEEN 0 AND 999999999 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_owner_hex IS NULL OR p_owner_hex !~ '^[0-9a-f]{32}$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF r.lease_kind IS DISTINCT FROM 'QUERY' OR r.lease_owner IS DISTINCT FROM decode(p_owner_hex,'hex') OR r.record_version<>p_version OR r.lease_expires_at IS NULL OR ((p_now->>'epoch_seconds')::numeric*1000000000+(p_now->>'nanosecond')::numeric)>=extract(epoch FROM r.lease_expires_at)*1000000000 THEN RETURN jsonb_build_object('outcome','RELEASED');END IF;pg_us:=mod((p_now->>'epoch_seconds')::numeric*1000000+div((p_now->>'nanosecond')::numeric,1000)-946684800000000,18446744073709551616);IF pg_us<0 THEN pg_us:=pg_us+18446744073709551616;END IF;IF pg_us>=9223372036854775808 THEN pg_us:=pg_us-18446744073709551616;END IF;
IF pg_us=9223372036854775807 THEN now_at:='infinity'::timestamptz;ELSIF pg_us=-9223372036854775808 THEN now_at:='-infinity'::timestamptz;ELSE now_at:='2000-01-01T00:00:00Z'::timestamptz+(div(pg_us,86400000000)::text||' days '||mod(pg_us,86400000000)::text||' microseconds')::interval;END IF;
expiry_ns:=((p_now->>'epoch_seconds')::numeric*1000000000+(p_now->>'nanosecond')::numeric)+60000000000;expiry:=jsonb_build_object('epoch_seconds',floor(expiry_ns/1000000000)::text,'nanosecond',expiry_ns-floor(expiry_ns/1000000000)*1000000000);
pg_us:=mod((expiry->>'epoch_seconds')::numeric*1000000+div((expiry->>'nanosecond')::numeric,1000)-946684800000000,18446744073709551616);IF pg_us<0 THEN pg_us:=pg_us+18446744073709551616;END IF;IF pg_us>=9223372036854775808 THEN pg_us:=pg_us-18446744073709551616;END IF;
IF pg_us=9223372036854775807 THEN expires_at:='infinity'::timestamptz;ELSIF pg_us=-9223372036854775808 THEN expires_at:='-infinity'::timestamptz;ELSE expires_at:='2000-01-01T00:00:00Z'::timestamptz+(div(pg_us,86400000000)::text||' days '||mod(pg_us,86400000000)::text||' microseconds')::interval;END IF;
UPDATE public.refunds SET lease_kind=NULL,lease_owner=NULL,lease_expires_at=NULL,next_query_at=expires_at,record_version=record_version+1,updated_at=now_at WHERE id=p_refund;RETURN jsonb_build_object('outcome','RELEASED');
 EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS failure_state=RETURNED_SQLSTATE,failure_constraint=CONSTRAINT_NAME;
 IF failure_state='P1000' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;RETURN jsonb_build_object('outcome','UNAVAILABLE');
 END;
END
$order_rpc$;

CREATE OR REPLACE FUNCTION public.order_refund_pending_v1(p_owner numeric,p_after numeric,p_limit integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER
SET search_path=pg_catalog,public SET TimeZone='UTC' AS $order_rpc$
DECLARE owner_id numeric;r public.refunds%ROWTYPE;out_rows jsonb;
failure_state text;failure_constraint text;
BEGIN
 IF current_user<>'authenticated' OR auth.role() IS DISTINCT FROM 'authenticated' OR auth.uid() IS DISTINCT FROM '__ORDER_SERVICE_UID__' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ORDER_RUNTIME_FORBIDDEN';END IF;
 BEGIN
IF p_owner IS NULL OR p_owner<0 OR p_owner>18446744073709551615 OR p_owner<>trunc(p_owner) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_after IS NULL OR p_after<0 OR p_after>18446744073709551615 OR p_after<>trunc(p_after) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
SELECT id INTO owner_id FROM public.merchant_accounts WHERE bound_user_id=p_owner AND enabled=true AND deleted_at IS NULL AND role='OWNER';IF NOT FOUND THEN RETURN jsonb_build_object('outcome','FORBIDDEN');END IF;IF owner_id IS NULL OR owner_id NOT BETWEEN 0 AND 18446744073709551615 OR (p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;out_rows:='[]'::jsonb;FOR r IN SELECT * FROM public.refunds WHERE id>p_after AND (materialization_state='PENDING_MANUAL' OR provider_state IN ('CREATE_UNKNOWN','PROCESSING','CLOSED')) ORDER BY id LIMIT p_limit LOOP out_rows:=out_rows||jsonb_build_array(jsonb_build_object('id',r.id::text,'prepayment_id',r.prepayment_id::text,'order_id',r.order_id::text,'state',r.provider_state,'materialization_state',r.materialization_state,'amount_cents',r.amount_cents::text,'currency',r.currency,'requested_kind',(CASE WHEN r.created_at IS NULL THEN 'NULL' WHEN r.created_at='infinity'::timestamptz THEN 'POSITIVE_INFINITY' WHEN r.created_at='-infinity'::timestamptz THEN 'NEGATIVE_INFINITY' ELSE 'FINITE' END),'requested_microseconds',(CASE WHEN r.created_at IS NOT NULL AND isfinite(r.created_at) THEN (extract(epoch FROM r.created_at)*1000000-946684800000000)::bigint::text ELSE NULL END),'provider_refund_id_hex',encode(r.provider_refund_id,'hex'),'pending_reason',r.pending_reason_code));END LOOP;RETURN jsonb_build_object('outcome','FOUND','refunds',out_rows);
 EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS failure_state=RETURNED_SQLSTATE,failure_constraint=CONSTRAINT_NAME;
 IF failure_state='P1000' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;RETURN jsonb_build_object('outcome','UNAVAILABLE');
 END;
END
$order_rpc$;
